CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 REAL COLLATE NOCASE, c1 ANY, c2 TEXT DEFAULT 'd', c3 ANY, c4 REAL) STRICT;
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 INTEGER CHECK(c0 IS NULL OR length(c0) < 40), c1 REAL CHECK(c1 IS NULL OR length(c1) < 40), c2 TEXT, c3  DEFAULT 'd', c4 TEXT DEFAULT 'd');
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4) VALUES(-251, NULL, -694.2142, NULL, x'b229');
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4) VALUES(' pad ', NULL, NULL, 5, -848);
SELECT date('2038-01-19 03:14:07'), time('2038-01-19 03:14:07'), datetime('2038-01-19 03:14:07', '+12 hours'), julianday('2038-01-19 03:14:07'), strftime('%s', '2038-01-19 03:14:07'), unixepoch('2038-01-19 03:14:07'), timediff('2024-03-01', '2023-01-15');
SELECT date('1970-01-01'), time('1970-01-01'), datetime('1970-01-01', 'weekday 0'), julianday('1970-01-01'), strftime('%Y-%m-%d %H:%M:%S', '1970-01-01'), unixepoch('1970-01-01'), timediff('2024-03-01', '2023-01-15');
SELECT date('1970-01-01'), time('1970-01-01'), datetime('1970-01-01', '+1 day'), julianday('1970-01-01'), strftime('%f', '1970-01-01'), unixepoch('1970-01-01'), timediff('2024-03-01', '2023-01-15');
SELECT date('2024-02-29'), time('2024-02-29'), datetime('2024-02-29', '+12 hours'), julianday('2024-02-29'), strftime('%J', '2024-02-29'), unixepoch('2024-02-29'), timediff('2024-03-01', '2023-01-15');
SELECT date('2000-01-01 12:34:56'), time('2000-01-01 12:34:56'), datetime('2000-01-01 12:34:56', 'unixepoch'), julianday('2000-01-01 12:34:56'), strftime('%J', '2000-01-01 12:34:56'), unixepoch('2000-01-01 12:34:56'), timediff('2024-03-01', '2023-01-15');
SELECT id, c1, group_concat(id, '.') OVER (PARTITION BY c1 IS NULL ORDER BY id) FROM t1 ORDER BY id;
SELECT id, c0, count(*) OVER (ORDER BY id) FROM t1 ORDER BY id;
